-- Previous questions are archived, never deleted. Student history checks fail closed.
BEGIN ISOLATION LEVEL REPEATABLE READ;
SET LOCAL lock_timeout = '8s';
SET LOCAL statement_timeout = '60s';
DO $patch$
DECLARE e uuid; before_state jsonb; after_state jsonb; old_bank jsonb; n integer; payload jsonb := $bank${"1":[{"question":"A quantos litros corresponde 1 m³ de água?","options":["1.000 litros","100 litros","10 litros","10.000 litros","100.000 litros"],"correct_answer":0,"explanation":"Um metro cúbico corresponde a mil litros. Fonte: capítulo 1, página PDF 9. Trecho: “Cada m³ corresponde a 1.000 litros.”. SHA-256 do PDF: 2313593756ab1aee43d6b85e6307520df32d395ae593521a16275ff4f48ed0db.","order_index":0,"page":9,"excerpt":"Cada m³ corresponde a 1.000 litros."},{"question":"Qual prefixo SI representa 1.000.000.000 (um bilhão)?","options":["quilo (k)","giga (G)","mega (M)","mili (m)","micro (μ)"],"correct_answer":1,"explanation":"A tabela relaciona giga (G) a um bilhão, isto é, 10⁹. Fonte: capítulo 1, página PDF 6. Trecho: “| giga | G | 109 | | Bilhão | 1 000 000 000 |”. SHA-256 do PDF: 2313593756ab1aee43d6b85e6307520df32d395ae593521a16275ff4f48ed0db.","order_index":1,"page":6,"excerpt":"| giga | G | 109 | | Bilhão | 1 000 000 000 |"},{"question":"Qual fórmula calcula o volume de uma piscina retangular, com todas as medidas em metros?","options":["Comprimento × largura, sem profundidade","Comprimento + largura + profundidade média","Comprimento × largura × profundidade média","Comprimento × largura ÷ profundidade média","Comprimento × largura × profundidade média × 0,785"],"correct_answer":2,"explanation":"Para um tanque retangular, multiplica-se a área da superfície pela profundidade média. Fonte: capítulo 1, página PDF 9. Trecho: “comprimento (m) x largura (m) x profundidade (m).”. SHA-256 do PDF: 2313593756ab1aee43d6b85e6307520df32d395ae593521a16275ff4f48ed0db.","order_index":2,"page":9,"excerpt":"comprimento (m) x largura (m) x profundidade (m)."},{"question":"Qual é o volume de uma piscina retangular com 8 m de comprimento, 4 m de largura e 1,4 m de profundidade média?","options":["32,0 m³","13,4 m³","56,0 m³","44,8 m³","4,48 m³"],"correct_answer":3,"explanation":"O cálculo é 8 × 4 × 1,4 = 44,8 m³. Fonte: capítulo 1, página PDF 9. Trecho: “8 (m) x 4 (m) x 1, 4 (m) = 44,8 m³.”. SHA-256 do PDF: 2313593756ab1aee43d6b85e6307520df32d395ae593521a16275ff4f48ed0db.","order_index":3,"page":9,"excerpt":"8 (m) x 4 (m) x 1, 4 (m) = 44,8 m³."},{"question":"Para um spa circular de raio r e profundidade média h, qual fórmula calcula o volume, adotando π = 3,14?","options":["V = 3,14 × r × h","V = 2 × 3,14 × r","V = 3,14 × r² ÷ h","V = r² × h ÷ 3,14","V = 3,14 × r² × h"],"correct_answer":4,"explanation":"A área circular é 3,14 × r²; seu produto pela profundidade média fornece o volume. Fonte: capítulo 1, página PDF 15. Trecho: “Para sabermos o volume, basta multiplicar a área da circunferência pela profundidade média:”. SHA-256 do PDF: 2313593756ab1aee43d6b85e6307520df32d395ae593521a16275ff4f48ed0db.","order_index":4,"page":15,"excerpt":"Para sabermos o volume, basta multiplicar a área da circunferência pela profundidade média:"},{"question":"A quantos quilogramas correspondem 250 gramas?","options":["0,25 kg","0,025 kg","2,5 kg","25 kg","250 kg"],"correct_answer":0,"explanation":"250 ÷ 1.000 = 0,25 kg. Fonte: capítulo 1, página PDF 8. Trecho: “gramas ÷ 1.000 = quilos (kg)”. SHA-256 do PDF: 2313593756ab1aee43d6b85e6307520df32d395ae593521a16275ff4f48ed0db.","order_index":5,"page":8,"excerpt":"gramas ÷ 1.000 = quilos (kg)"},{"question":"A quantos litros correspondem 3.000 mililitros?","options":["0,3 litro","3 litros","30 litros","300 litros","3.000 litros"],"correct_answer":1,"explanation":"3.000 ÷ 1.000 = 3 litros. Fonte: capítulo 1, página PDF 7. Trecho: “Ou seja, mililitros ÷ 1.000 = litros.”. SHA-256 do PDF: 2313593756ab1aee43d6b85e6307520df32d395ae593521a16275ff4f48ed0db.","order_index":6,"page":7,"excerpt":"Ou seja, mililitros ÷ 1.000 = litros."},{"question":"Como calcular o volume de reposição de uma piscina retangular quando o nível baixa?","options":["Multiplicar a área pela profundidade total original","Dividir a área pela altura que baixou em centímetros","Multiplicar a área da superfície pela altura que baixou, convertida para metros","Multiplicar somente comprimento por largura, sem altura","Somar a área à altura que baixou"],"correct_answer":2,"explanation":"A reposição é a área superficial multiplicada pela queda de nível em metros. Fonte: capítulo 1, página PDF 14. Trecho: “Volume adicional = 8 (m) x 4 (m) x 0,15 (m) = 4,8m³”. SHA-256 do PDF: 2313593756ab1aee43d6b85e6307520df32d395ae593521a16275ff4f48ed0db.","order_index":7,"page":14,"excerpt":"Volume adicional = 8 (m) x 4 (m) x 0,15 (m) = 4,8m³"},{"question":"Na conversão usada para calcular reposição de água, quanto valem 5 centímetros em metros?","options":["0,5 m","0,005 m","5 m","0,05 m","50 m"],"correct_answer":3,"explanation":"Como um metro tem cem centímetros, 5 cm ÷ 100 = 0,05 m. Fonte: capítulo 1, página PDF 13. Trecho: “15 centímetros = (15 ÷ 100) = 0,15m”. SHA-256 do PDF: 2313593756ab1aee43d6b85e6307520df32d395ae593521a16275ff4f48ed0db.","order_index":8,"page":13,"excerpt":"15 centímetros = (15 ÷ 100) = 0,15m"},{"question":"Qual alternativa define a área da piscina e sua unidade?","options":["A capacidade total de água, medida em m³","A distância do centro à borda, medida em litros","A profundidade média, medida em m²","A quantidade de água evaporada, medida em m","A superfície do espelho d'água, medida em m²"],"correct_answer":4,"explanation":"Área é a superfície do espelho d’água, em metros quadrados. Fonte: capítulo 1, página PDF 9. Trecho: “Fórmula da superfície ou área (m²) = comprimento (m) x largura (m)”. SHA-256 do PDF: 2313593756ab1aee43d6b85e6307520df32d395ae593521a16275ff4f48ed0db.","order_index":9,"page":9,"excerpt":"Fórmula da superfície ou área (m²) = comprimento (m) x largura (m)"}],"2":[{"question":"Qual conduta o capítulo orienta quando um usuário apresenta sintomas suspeitos de doença?","options":["Encaminhá-lo ao atendimento médico para avaliação diagnóstica","O tratador deve emitir o diagnóstico clínico","O tratador deve prescrever um medicamento","Concluir a causa apenas pela aparência da água","Liberar o uso da piscina enquanto houver sintomas"],"correct_answer":0,"explanation":"O tratador oferece orientações gerais, mas o diagnóstico cabe à equipe médica. Fonte: capítulo 2, página PDF 1. Trecho: “devem ser imediatamente encaminhados ao atendimento médico para avaliação de diagnóstico.”. SHA-256 do PDF: 69ba67b402090f33592849d8236705ba5cf6c09a2d506bfe1b08656dc7fa91ed.","order_index":0,"page":1,"excerpt":"devem ser imediatamente encaminhados ao atendimento médico para avaliação de diagnóstico."},{"question":"Quais são vias de introdução de contaminantes na água citadas no capítulo?","options":["Somente os usuários, nunca os animais","Ar, solo, animais, usuários e a própria água utilizada","Somente a água de abastecimento","Somente equipamentos de aquecimento","Apenas objetos visíveis no fundo"],"correct_answer":1,"explanation":"A contaminação pode ter origem no ambiente, nos usuários, em animais ou na água de abastecimento. Fonte: capítulo 2, página PDF 3. Trecho: “pelo ar, solo, animais, outros usuários ou mesmo a própria água utilizada.”. SHA-256 do PDF: 69ba67b402090f33592849d8236705ba5cf6c09a2d506bfe1b08656dc7fa91ed.","order_index":1,"page":3,"excerpt":"pelo ar, solo, animais, outros usuários ou mesmo a própria água utilizada."},{"question":"Quais verificações regulares são destacadas para o controle de contaminantes?","options":["Somente a temperatura do ar","Somente a profundidade da piscina","Níveis de desinfetantes e pH","Somente o volume do reservatório","Apenas o consumo elétrico da bomba"],"correct_answer":2,"explanation":"O texto destaca testes regulares de desinfetante e pH, e não somente observação visual. Fonte: capítulo 2, página PDF 4. Trecho: “A garantia de uma água livre de contaminantes é a verificação dos níveis de desinfetantes e de pH regularmente.”. SHA-256 do PDF: 69ba67b402090f33592849d8236705ba5cf6c09a2d506bfe1b08656dc7fa91ed.","order_index":2,"page":4,"excerpt":"A garantia de uma água livre de contaminantes é a verificação dos níveis de desinfetantes e de pH regularmente."},{"question":"Qual risco decorre de desinfetante insuficiente na piscina?","options":["Eliminação de todos os patógenos pela transparência","Desinfecção completa sem necessidade de controle","Inativação automática dos microrganismos pela circulação","Maior risco de exposição a agentes infecciosos","Proteção residual assegurada independentemente da concentração"],"correct_answer":3,"explanation":"A insuficiência de desinfetante compromete a proteção contra agentes infecciosos. Fonte: capítulo 2, página PDF 5. Trecho: “A falta de desinfetante suficiente na água da piscina ou spa coloca o ambiente em risco do agente infeccioso”. SHA-256 do PDF: 69ba67b402090f33592849d8236705ba5cf6c09a2d506bfe1b08656dc7fa91ed.","order_index":3,"page":5,"excerpt":"A falta de desinfetante suficiente na água da piscina ou spa coloca o ambiente em risco do agente infeccioso"},{"question":"Qual par é apresentado no capítulo como exemplo de protozoários associados a contágios em piscinas?","options":["E. coli e Shigella","Hepatite A e Norovírus","E. coli e Norovírus","Shigella e Hepatite A","Giardia e Cryptosporidium"],"correct_answer":4,"explanation":"O capítulo classifica Giardia e Cryptosporidium entre os protozoários. Fonte: capítulo 2, página PDF 6. Trecho: “Giardia e o Cryptosporidium”. SHA-256 do PDF: 69ba67b402090f33592849d8236705ba5cf6c09a2d506bfe1b08656dc7fa91ed.","order_index":4,"page":6,"excerpt":"Giardia e o Cryptosporidium"},{"question":"Por que o Cryptosporidium representa um desafio para a desinfecção rotineira?","options":["Sua proteção permite resistir por dias aos níveis normais de cloro","Porque é uma bactéria eliminada apenas pela filtração de folhas","Porque é um mineral que reage com o cálcio","Porque só se multiplica em água salgada","Porque é um vírus destruído instantaneamente por qualquer dose de cloro"],"correct_answer":0,"explanation":"A camada protetora do Cryptosporidium dificulta sua inativação pelos níveis rotineiros de cloro. Fonte: capítulo 2, página PDF 8. Trecho: “possui uma ca- mada de proteção externa que permite a sobrevivência do organismo em condições de desinfecção por cloro, permanecendo ativo durante dias.”. SHA-256 do PDF: 69ba67b402090f33592849d8236705ba5cf6c09a2d506bfe1b08656dc7fa91ed.","order_index":5,"page":8,"excerpt":"possui uma ca- mada de proteção externa que permite a sobrevivência do organismo em condições de desinfecção por cloro, permanecendo ativo durante dias."},{"question":"Como o capítulo caracteriza as bactérias?","options":["Organismos sempre multicelulares","Organismos unicelulares que se multiplicam facilmente em ambientes favoráveis","Compostos minerais dissolvidos na água","Produtos químicos oxidantes","Equipamentos de retenção de partículas"],"correct_answer":1,"explanation":"O texto descreve bactérias como organismos de uma única célula. Fonte: capítulo 2, página PDF 9. Trecho: “Bactérias são unicelulares que, em ambientes favoráveis, se multipli- cam com facilidade.”. SHA-256 do PDF: 69ba67b402090f33592849d8236705ba5cf6c09a2d506bfe1b08656dc7fa91ed.","order_index":6,"page":9,"excerpt":"Bactérias são unicelulares que, em ambientes favoráveis, se multipli- cam com facilidade."},{"question":"Qual é a primeira ação no protocolo geral após um acidente com fezes ou vômito na piscina?","options":["Aspirar o material com o filtro na posição filtrar","Aplicar aromatizante e manter os banhistas na água","Retirar todos os banhistas da água e isolar a área","Esperar o material afundar para agir","Reduzir o tempo de filtração sem interditar a piscina"],"correct_answer":2,"explanation":"A primeira ação é retirar os usuários da área da piscina ou spa. Fonte: capítulo 2, página PDF 15. Trecho: “Retire todos os usuários da área da piscina ou spa imediatamente após o incidente;”. SHA-256 do PDF: 69ba67b402090f33592849d8236705ba5cf6c09a2d506bfe1b08656dc7fa91ed.","order_index":7,"page":15,"excerpt":"Retire todos os usuários da área da piscina ou spa imediatamente após o incidente;"},{"question":"Um acidente contaminante ocorre em uma piscina cujo sistema filtrante atende a outros tanques. Qual ação o texto indica?","options":["Retirar usuários apenas do tanque onde o material é visível","Manter os demais tanques abertos sem avaliação","Transferir imediatamente os usuários para o tanque interligado","Retirar os usuários de todos os ambientes atendidos pelo mesmo sistema","Reduzir a circulação e manter todos na água"],"correct_answer":3,"explanation":"O compartilhamento da filtração pode levar contaminantes aos demais ambientes; todos devem ficar sem usuários. Fonte: capítulo 2, página PDF 15. Trecho: “todos esses ambientes devem ser esvaziados de usuários”. SHA-256 do PDF: 69ba67b402090f33592849d8236705ba5cf6c09a2d506bfe1b08656dc7fa91ed.","order_index":8,"page":15,"excerpt":"todos esses ambientes devem ser esvaziados de usuários"},{"question":"Quais dados devem compor o registro de um incidente contaminante?","options":["Somente o preço do produto utilizado","Apenas a quantidade de banhistas do mês","Somente a cor da água antes do tratamento","Apenas o nome comercial do filtro","Data, hora, tipo de evento e medições do acidente e após a desinfecção"],"correct_answer":4,"explanation":"O registro precisa documentar a ocorrência e as condições medidas antes e após a desinfecção. Fonte: capítulo 2, página PDF 16. Trecho: “contendo data, hora, tipo de even- to (diarreia, vômito, sangue e etc), medições do momento do acidente e medições após a desinfecção.”. SHA-256 do PDF: 69ba67b402090f33592849d8236705ba5cf6c09a2d506bfe1b08656dc7fa91ed.","order_index":9,"page":16,"excerpt":"contendo data, hora, tipo de even- to (diarreia, vômito, sangue e etc), medições do momento do acidente e medições após a desinfecção."}],"3":[{"question":"O que caracteriza o residual deixado pelo cloro na água?","options":["Desinfetante que permanece disponível para agir sobre novas contaminações","Areia que permanece no fundo depois da filtração","Somente a cor azul produzida pelo produto","O volume perdido na retrolavagem","Um resíduo que substitui todos os testes de água"],"correct_answer":0,"explanation":"Residual é a parcela de desinfetante que permanece disponível na água. Fonte: capítulo 3, página PDF 3. Trecho: “permanece ativo por longos períodos na água, promovendo assim uma desinfecção contínua, é o que cha- mamos de residual.”. SHA-256 do PDF: 55ea797a91c60d81877077ff650e8df612bf601296ee2133209c6a406b92a9fd.","order_index":0,"page":3,"excerpt":"permanece ativo por longos períodos na água, promovendo assim uma desinfecção contínua, é o que cha- mamos de residual."},{"question":"Qual desinfetante é líquido e, segundo a apostila, tende a elevar o pH?","options":["Tricloro em pastilhas","Hipoclorito de sódio","Dicloro granulado","Ácido cianúrico","Bissulfato de sódio"],"correct_answer":1,"explanation":"O hipoclorito de sódio é líquido e tem pH elevado; o texto informa alteração do pH após seu uso. Fonte: capítulo 3, página PDF 9. Trecho: “É um desinfetante líquido”. SHA-256 do PDF: 55ea797a91c60d81877077ff650e8df612bf601296ee2133209c6a406b92a9fd.","order_index":1,"page":9,"excerpt":"É um desinfetante líquido"},{"question":"Qual produto pode aumentar a quantidade de cálcio na água quando usado continuamente?","options":["Hipoclorito de sódio","Ácido muriático","Hipoclorito de cálcio","Bissulfato de sódio","Cloreto de sódio usado na eletrólise"],"correct_answer":2,"explanation":"O uso contínuo de hipoclorito de cálcio aumenta o cálcio na água. Fonte: capítulo 3, página PDF 9. Trecho: “O uso contínuo deste produto, resulta em níveis altos de cálcio na água (dureza cálcica)”. SHA-256 do PDF: 55ea797a91c60d81877077ff650e8df612bf601296ee2133209c6a406b92a9fd.","order_index":2,"page":9,"excerpt":"O uso contínuo deste produto, resulta em níveis altos de cálcio na água (dureza cálcica)"},{"question":"Qual substância protege o cloro estabilizado da ação dos raios solares?","options":["Ácido muriático","Bicarbonato de sódio","Cloreto de cálcio","Ácido cianúrico","Bissulfato de sódio"],"correct_answer":3,"explanation":"O ácido cianúrico protege o cloro da ação da radiação solar. Fonte: capítulo 3, página PDF 11. Trecho: “ele atua como um protetor solar para o cloro, protegendo dos efeitos da luz ultravioleta emitidas pelo sol.”. SHA-256 do PDF: 55ea797a91c60d81877077ff650e8df612bf601296ee2133209c6a406b92a9fd.","order_index":3,"page":11,"excerpt":"ele atua como um protetor solar para o cloro, protegendo dos efeitos da luz ultravioleta emitidas pelo sol."},{"question":"Qual cloro estabilizado é descrito como granulado de dissolução rápida?","options":["Tricloro em pastilhas de dissolução lenta","Hipoclorito de sódio líquido","Hipoclorito de cálcio inorgânico","Ácido cianúrico isolado","Dicloro"],"correct_answer":4,"explanation":"A seção Dicloro informa grande solubilidade e apresentação habitual granulada. Fonte: capítulo 3, página PDF 12. Trecho: “Extremamente solúvel, com pH neutro”. SHA-256 do PDF: 55ea797a91c60d81877077ff650e8df612bf601296ee2133209c6a406b92a9fd.","order_index":4,"page":12,"excerpt":"Extremamente solúvel, com pH neutro"},{"question":"Qual prática deve ser evitada devido ao risco de reação química violenta?","options":["Misturar cloro orgânico e inorgânico no mesmo recipiente","Manter baldes separados para tipos diferentes de cloro","Identificar os medidores de cada produto","Consultar a orientação do fabricante antes da aplicação","Guardar os produtos nas embalagens identificadas"],"correct_answer":0,"explanation":"Não se devem misturar produtos químicos, incluindo cloros orgânicos e inorgânicos. Fonte: capítulo 3, página PDF 19. Trecho: “Nunca realizar a mistura de produtos químicos, mesmo sendo do mesmo fabricante”. SHA-256 do PDF: 55ea797a91c60d81877077ff650e8df612bf601296ee2133209c6a406b92a9fd.","order_index":5,"page":19,"excerpt":"Nunca realizar a mistura de produtos químicos, mesmo sendo do mesmo fabricante"},{"question":"Qual substância é apresentada como o agente ativo da desinfecção formada quando o cloro reage com a água?","options":["Ácido cianúrico","Ácido hipocloroso","Bicarbonato de sódio","Cloreto de cálcio","Carbonato de sódio"],"correct_answer":1,"explanation":"O ácido hipocloroso é o agente responsável pela inativação descrita. Fonte: capítulo 3, página PDF 5. Trecho: “O ácido hipocloroso é responsável pela inativação do patógeno e algas”. SHA-256 do PDF: 55ea797a91c60d81877077ff650e8df612bf601296ee2133209c6a406b92a9fd.","order_index":6,"page":5,"excerpt":"O ácido hipocloroso é responsável pela inativação do patógeno e algas"},{"question":"O forte odor associado ao cloro combinado e à irritação dos olhos está relacionado principalmente a quê?","options":["À presença de bicarbonato que aumenta a alcalinidade","À ausência de qualquer matéria orgânica na piscina","À formação de cloraminas pela reação com contaminantes orgânicos","À ação exclusiva do sal mineral sem desinfetante","À quantidade de areia limpa no filtro"],"correct_answer":2,"explanation":"Cloraminas são subprodutos relacionados a odor forte e irritações. Fonte: capítulo 3, página PDF 6. Trecho: ““Cloramina”, causador de odores fortes, irritação nos olhos, peles e mucosas.”. SHA-256 do PDF: 55ea797a91c60d81877077ff650e8df612bf601296ee2133209c6a406b92a9fd.","order_index":7,"page":6,"excerpt":"“Cloramina”, causador de odores fortes, irritação nos olhos, peles e mucosas."},{"question":"Como atua o sistema auxiliar de luz ultravioleta descrito no capítulo?","options":["Uma resistência aquece a água para remover minerais","Um filtro de areia aumenta automaticamente o cloro livre","Uma pastilha de ácido cianúrico dissolve o biofilme","A água atravessa uma câmara de radiação UV que danifica o DNA dos patógenos","Ímãs substituem todos os reagentes e testes"],"correct_answer":3,"explanation":"O UV atua em uma câmara no circuito de circulação e danifica o DNA do patógeno. Fonte: capítulo 3, página PDF 16. Trecho: “a ação do UV danifica o DNA do patógeno”. SHA-256 do PDF: 55ea797a91c60d81877077ff650e8df612bf601296ee2133209c6a406b92a9fd.","order_index":8,"page":16,"excerpt":"a ação do UV danifica o DNA do patógeno"},{"question":"Qual conjunto o gerador utiliza para produzir cloro?","options":["Água sem sal passando apenas por um filtro de areia","Ácido cianúrico aquecido em coletor solar","Bicarbonato de sódio e lâmpada sem corrente elétrica","Cloreto de cálcio em um reservatório sem eletricidade","Água com cloreto de sódio passando pelo dispositivo que aplica eletricidade"],"correct_answer":4,"explanation":"O gerador combina água, cloreto de sódio e eletricidade para gerar cloro. Fonte: capítulo 3, página PDF 13. Trecho: “produção de cloro a partir da mistura de sal de cloreto de sódio, água e eletricidade.”. SHA-256 do PDF: 55ea797a91c60d81877077ff650e8df612bf601296ee2133209c6a406b92a9fd.","order_index":9,"page":13,"excerpt":"produção de cloro a partir da mistura de sal de cloreto de sódio, água e eletricidade."}],"4":[{"question":"Qual é a função principal da alcalinidade total?","options":["Amortecer variações bruscas do pH por efeito tampão","Medir diretamente a quantidade de cloro combinado","Substituir a filtração de partículas sólidas","Indicar somente a temperatura da água","Eliminar a necessidade de desinfecção"],"correct_answer":0,"explanation":"A alcalinidade funciona como resistência às alterações do pH. Fonte: capítulo 4, página PDF 3. Trecho: “capacidade da água em resistir as alterações nos níveis de pH”. SHA-256 do PDF: 8b58a8f6756a2818363f029e9b521589ca57eaae5f3a9509fb3cca8b32414976.","order_index":0,"page":3,"excerpt":"capacidade da água em resistir as alterações nos níveis de pH"},{"question":"Qual faixa ideal de alcalinidade total é apresentada na apostila atual?","options":["20 a 40 ppm","80 a 120 ppm","30 a 50 ppm","200 a 400 ppm","500 a 800 ppm"],"correct_answer":1,"explanation":"O PDF selecionado informa 80 a 120 ppm de alcalinidade total. Fonte: capítulo 4, página PDF 3. Trecho: “Os níveis ideais para a alcalinidade total de operação devem ser na faixa entre 80 a 120 ppm (mg/L).”. SHA-256 do PDF: 8b58a8f6756a2818363f029e9b521589ca57eaae5f3a9509fb3cca8b32414976.","order_index":1,"page":3,"excerpt":"Os níveis ideais para a alcalinidade total de operação devem ser na faixa entre 80 a 120 ppm (mg/L)."},{"question":"Qual produto é indicado para elevar a alcalinidade total baixa?","options":["Ácido muriático","Bissulfato de sódio","Bicarbonato de sódio","Ácido cianúrico","Algicida à base de cobre"],"correct_answer":2,"explanation":"O bicarbonato é indicado para elevar a alcalinidade total. Fonte: capítulo 4, página PDF 5. Trecho: “Para elevar os ní- veis de alcalinidade total, recomenda-se o uso de bicarbonato de sódio”. SHA-256 do PDF: 8b58a8f6756a2818363f029e9b521589ca57eaae5f3a9509fb3cca8b32414976.","order_index":2,"page":5,"excerpt":"Para elevar os ní- veis de alcalinidade total, recomenda-se o uso de bicarbonato de sódio"},{"question":"Qual faixa de pH é apresentada na sequência geral de equilíbrio da água do PDF?","options":["6,0 a 6,5","6,5 a 6,9","7,8 a 8,2","7,2 a 7,8","8,5 a 9,0"],"correct_answer":3,"explanation":"A faixa apresentada no PDF selecionado é 7,2 a 7,8, e não 7,2 a 7,6. Fonte: capítulo 4, página PDF 2. Trecho: “pH: entre 7,2 e 7,8”. SHA-256 do PDF: 8b58a8f6756a2818363f029e9b521589ca57eaae5f3a9509fb3cca8b32414976.","order_index":3,"page":2,"excerpt":"pH: entre 7,2 e 7,8"},{"question":"Qual afirmação diferencia dureza total e dureza de cálcio?","options":["Dureza total é apenas o pH multiplicado por dez","Dureza de cálcio é igual ao cloro livre","Dureza total mede somente a temperatura","Dureza de cálcio mede apenas a alcalinidade","A dureza total é a soma de cálcio e magnésio"],"correct_answer":4,"explanation":"O texto distingue dureza total da contribuição específica do cálcio. Fonte: capítulo 4, página PDF 14. Trecho: “a dureza to- tal é a soma de cálcio e de magnésio”. SHA-256 do PDF: 8b58a8f6756a2818363f029e9b521589ca57eaae5f3a9509fb3cca8b32414976.","order_index":4,"page":14,"excerpt":"a dureza to- tal é a soma de cálcio e de magnésio"},{"question":"Que problemas nos equipamentos o equilíbrio químico ajuda a prevenir?","options":["Corrosão e incrustações","Desgaste elétrico causado exclusivamente por falta de tensão","Falha de iluminação causada apenas por lâmpada queimada","Aprisionamento causado exclusivamente por grelha ausente","Problemas de acesso causados apenas por portão quebrado"],"correct_answer":0,"explanation":"O equilíbrio protege as superfícies e equipamentos contra corrosão e depósitos. Fonte: capítulo 4, página PDF 1. Trecho: “protege os equipamentos contra corro- são e incrustações.”. SHA-256 do PDF: 8b58a8f6756a2818363f029e9b521589ca57eaae5f3a9509fb3cca8b32414976.","order_index":5,"page":1,"excerpt":"protege os equipamentos contra corro- são e incrustações."},{"question":"Como o Total de Sólidos Dissolvidos é medido no método descrito?","options":["Pela altura da lâmina de água","Pela condutividade elétrica da água","Pelo número de rotações do motor","Pela pressão no ralo de fundo","Pela largura da piscina"],"correct_answer":1,"explanation":"Os compostos dissolvidos influenciam a condutividade, usada na medição de TSD. Fonte: capítulo 4, página PDF 16. Trecho: “O TSD é medido através da condutividade elétrica”. SHA-256 do PDF: 8b58a8f6756a2818363f029e9b521589ca57eaae5f3a9509fb3cca8b32414976.","order_index":6,"page":16,"excerpt":"O TSD é medido através da condutividade elétrica"},{"question":"Qual intervalo do Índice de Saturação (IS) caracteriza água balanceada no PDF?","options":["De −3,0 a −1,0","De +1,0 a +3,0","De −0,3 a +0,3","Somente abaixo de −0,3","Somente acima de +0,3"],"correct_answer":2,"explanation":"O intervalo do índice de saturação apresentado é −0,3 a +0,3. Fonte: capítulo 4, página PDF 18. Trecho: “A faixa ideal de IS é entre -0,3 e +0,3 (água balanceada)”. SHA-256 do PDF: 8b58a8f6756a2818363f029e9b521589ca57eaae5f3a9509fb3cca8b32414976.","order_index":7,"page":18,"excerpt":"A faixa ideal de IS é entre -0,3 e +0,3 (água balanceada)"},{"question":"Qual tendência corresponde a um IS abaixo de −0,3?","options":["Água incrustante","Equilíbrio garantido independentemente do pH","Ausência de cálcio obrigatoriamente igual a zero","Água corrosiva","Desinfecção completa sem cloro"],"correct_answer":3,"explanation":"Índices inferiores a −0,3 indicam tendência corrosiva. Fonte: capítulo 4, página PDF 18. Trecho: “índices abaixo de -0,3 esta água é considerada corrosiva”. SHA-256 do PDF: 8b58a8f6756a2818363f029e9b521589ca57eaae5f3a9509fb3cca8b32414976.","order_index":8,"page":18,"excerpt":"índices abaixo de -0,3 esta água é considerada corrosiva"},{"question":"Qual sequência de correção da água é expressamente indicada no PDF?","options":["pH, cloro e alcalinidade total","Cloro, dureza de cálcio e pH","Dureza de cálcio, pH e alcalinidade total","pH, dureza de cálcio e alcalinidade total","Alcalinidade total, pH e dureza de cálcio"],"correct_answer":4,"explanation":"A sequência do PDF é alcalinidade, pH e dureza de cálcio; não termina com cloro. Fonte: capítulo 4, página PDF 22. Trecho: “1º - ALCALINIDADE TOTAL; 2º - pH; 3º - DUREZA DE CÁLCIO.”. SHA-256 do PDF: 8b58a8f6756a2818363f029e9b521589ca57eaae5f3a9509fb3cca8b32414976.","order_index":9,"page":22,"excerpt":"1º - ALCALINIDADE TOTAL; 2º - pH; 3º - DUREZA DE CÁLCIO."}],"6":[{"question":"Cercas e portões dispensam supervisão direta dos usuários?","options":["Não; barreiras são impedimentos, mas não substituem a supervisão","Sim, sempre que houver uma placa","Sim, desde que a cerca seja pintada","Sim, se a água estiver transparente","Sim, durante o horário de maior movimento"],"correct_answer":0,"explanation":"A barreira complementa, mas não substitui, a supervisão. Fonte: capítulo 6, página PDF 4. Trecho: “Cercas, portões ou qualquer outro tipo de barreira nunca devem ser considerados substitutos da supervisão direta.”. SHA-256 do PDF: 1d9c2acf9e3f99e17ae806a1f79abc191dc7a2946d150950ddda7ba275d49031.","order_index":0,"page":4,"excerpt":"Cercas, portões ou qualquer outro tipo de barreira nunca devem ser considerados substitutos da supervisão direta."},{"question":"Qual característica do portão de acesso é recomendada para proteger crianças?","options":["Portão permanentemente aberto para facilitar acesso","Fechamento automático e trava fora do alcance dos pequenos","Trava no nível do chão acessível a crianças","Fechamento por corda sem qualquer trava","Portão que só pode ser fechado pelo lado da água"],"correct_answer":1,"explanation":"O acesso deve contar com fechamento e travamento automáticos, com trava fora do alcance de crianças. Fonte: capítulo 6, página PDF 4. Trecho: “dispositivo automático de fechamen- to e travamento”. SHA-256 do PDF: 1d9c2acf9e3f99e17ae806a1f79abc191dc7a2946d150950ddda7ba275d49031.","order_index":1,"page":4,"excerpt":"dispositivo automático de fechamen- to e travamento"},{"question":"Qual conjunto de informações de segurança deve ser sinalizado na área da piscina?","options":["Somente a marca da bomba e do filtro","Somente o preço dos produtos químicos","Profundidade, áreas escorregadias, permissão de mergulho e limite de banhistas","Apenas o horário da manutenção anual","Apenas a cor e o tipo do revestimento"],"correct_answer":2,"explanation":"O capítulo lista profundidade, risco de escorregamento, mergulho e quantidade máxima de banhistas. Fonte: capítulo 6, página PDF 7. Trecho: “Profundidade mínima e máxima de água do tanque”. SHA-256 do PDF: 1d9c2acf9e3f99e17ae806a1f79abc191dc7a2946d150950ddda7ba275d49031.","order_index":2,"page":7,"excerpt":"Profundidade mínima e máxima de água do tanque"},{"question":"Qual procedimento é obrigatório antes da entrada de usuários quando há capa de proteção instalada?","options":["Dobrar apenas uma ponta da capa","Manter a capa sobre a parte funda","Abrir um pequeno espaço no centro","Remover completamente a capa","Permitir o uso desde que alguém segure a borda"],"correct_answer":3,"explanation":"A cobertura total ou parcial durante o uso representa risco de afogamento. Fonte: capítulo 6, página PDF 5. Trecho: “deve ser completamente removida antes da entrada de usuários na piscina.”. SHA-256 do PDF: 1d9c2acf9e3f99e17ae806a1f79abc191dc7a2946d150950ddda7ba275d49031.","order_index":3,"page":5,"excerpt":"deve ser completamente removida antes da entrada de usuários na piscina."},{"question":"Alarmes de entrada na água podem substituir barreiras ou supervisão?","options":["Sim; qualquer alarme elimina a necessidade de cerca","Sim; se o sensor estiver ligado à rede elétrica","Sim; durante o dia não há necessidade de supervisão","Sim; somente crianças precisam de barreiras","Não; são recursos complementares"],"correct_answer":4,"explanation":"O texto trata alarmes como auxílio, nunca como substitutos das medidas principais. Fonte: capítulo 6, página PDF 8. Trecho: “os alarmes nunca devem substituir uma barreira ou supervisão efetiva.”. SHA-256 do PDF: 1d9c2acf9e3f99e17ae806a1f79abc191dc7a2946d150950ddda7ba275d49031.","order_index":4,"page":8,"excerpt":"os alarmes nunca devem substituir uma barreira ou supervisão efetiva."},{"question":"Como devem estar os equipamentos de segurança e salvamento em relação ao tanque?","options":["Facilmente acessíveis, próximos ao tanque","Guardados em depósito distante e trancado","Disponíveis apenas por agendamento","Misturados aos produtos químicos","Submersos na parte mais profunda"],"correct_answer":0,"explanation":"O acesso rápido aos equipamentos é requisito destacado no capítulo. Fonte: capítulo 6, página PDF 13. Trecho: “devem ser facilmente acessí- veis próximo ao tanque da piscina”. SHA-256 do PDF: 1d9c2acf9e3f99e17ae806a1f79abc191dc7a2946d150950ddda7ba275d49031.","order_index":5,"page":13,"excerpt":"devem ser facilmente acessí- veis próximo ao tanque da piscina"},{"question":"Na aproximação de chuva com risco de descargas elétricas, qual orientação o capítulo apresenta?","options":["Manter os usuários na água por ser mais seguro","Retirar os banhistas da água e do deck e abrigá-los em edificação protegida","Liberar apenas a parte rasa","Reunir todos junto às janelas","Permanecer na borda segurando corrimãos"],"correct_answer":1,"explanation":"A orientação inclui sair da água e do entorno e procurar abrigo apropriado. Fonte: capítulo 6, página PDF 19. Trecho: “todas as pessoas devem sair da área da piscina e serem alocadas em uma edificação protegida por para-raios”. SHA-256 do PDF: 1d9c2acf9e3f99e17ae806a1f79abc191dc7a2946d150950ddda7ba275d49031.","order_index":6,"page":19,"excerpt":"todas as pessoas devem sair da área da piscina e serem alocadas em uma edificação protegida por para-raios"},{"question":"Qual critério deve orientar a separação de produtos químicos no armazenamento?","options":["Somente a cor das embalagens","Somente o tamanho dos recipientes","Compatibilidade química","A ordem alfabética, ignorando reatividade","A proximidade da data de compra, sem considerar o produto"],"correct_answer":2,"explanation":"Produtos incompatíveis podem provocar incêndio, explosão e liberação de gases tóxicos. Fonte: capítulo 6, página PDF 20. Trecho: “é necessário separá-los e guardá-los com base em suas compatibilidades.”. SHA-256 do PDF: 1d9c2acf9e3f99e17ae806a1f79abc191dc7a2946d150950ddda7ba275d49031.","order_index":7,"page":20,"excerpt":"é necessário separá-los e guardá-los com base em suas compatibilidades."},{"question":"Que conduta é inadequada ao armazenar produtos químicos?","options":["Separar as famílias químicas","Manter as embalagens identificadas","Respeitar o prazo de validade","Colocar oxidantes junto a redutores ou ácidos junto a bases","Utilizar prateleiras resistentes"],"correct_answer":3,"explanation":"A alternativa incorreta aproxima reagentes incompatíveis; as demais são cuidados de armazenamento. Fonte: capítulo 6, página PDF 21. Trecho: “Cuidado para não colocar justapostos produtos que reagem entre si, como oxidante com redutores, ácidos com bases etc.”. SHA-256 do PDF: 1d9c2acf9e3f99e17ae806a1f79abc191dc7a2946d150950ddda7ba275d49031.","order_index":8,"page":21,"excerpt":"Cuidado para não colocar justapostos produtos que reagem entre si, como oxidante com redutores, ácidos com bases etc."},{"question":"Qual é a regra de segurança para a adição de químicos apresentada na revisão?","options":["Misturar produtos concentrados para reduzir o número de aplicações","Usar o mesmo balde com resíduos de cloros diferentes","Adicionar água diretamente à embalagem do produto concentrado","Combinar ácido e cloro no mesmo recipiente antes da aplicação","Não misturar produtos entre si e adicionar o produto à água, nunca água ao concentrado"],"correct_answer":4,"explanation":"O produto deve ser adicionado à água; o texto também proíbe misturar produtos diferentes (página 15). Fonte: capítulo 6, página PDF 16. Trecho: “sempre adicionar o produto químico à água e nunca a água ao produto químico”. SHA-256 do PDF: 1d9c2acf9e3f99e17ae806a1f79abc191dc7a2946d150950ddda7ba275d49031.","order_index":9,"page":16,"excerpt":"sempre adicionar o produto químico à água e nunca a água ao produto químico"}],"7":[{"question":"Quem deve realizar reparos que exigem conhecimento específico, como em equipamentos elétricos e aquecedores a gás?","options":["Técnico qualificado ou empresa prestadora de serviços especializada","Qualquer usuário que esteja disponível","O tratador, mesmo sem qualificação para a tarefa","O proprietário sem consulta técnica","Qualquer funcionário após observar um vídeo"],"correct_answer":0,"explanation":"O profissional não deve executar tarefas para as quais não seja qualificado. Fonte: capítulo 7, página PDF 1. Trecho: “Sempre recorra a um técnico qualificado ou empresa prestadora de serviços para realizar trabalhos de reparo”. SHA-256 do PDF: 1b50ab00af6310ca41a9fb3a8a80f8c7db67756ec3f321ba39d3a2704ac718cc.","order_index":0,"page":1,"excerpt":"Sempre recorra a um técnico qualificado ou empresa prestadora de serviços para realizar trabalhos de reparo"},{"question":"Por que produtos químicos não devem ser armazenados perto de motores e bombas?","options":["Porque impedem a leitura do volume da piscina","Porque emitem gases corrosivos","Porque alteram somente a cor do motor","Porque aumentam a largura das tubulações","Porque impedem a formação de bolhas na água"],"correct_answer":1,"explanation":"Os gases corrosivos podem afetar os equipamentos e a segurança do ambiente. Fonte: capítulo 7, página PDF 4. Trecho: “Produtos químicos emitem gases corrosivos e nunca devem ser armazenados perto de motores e bombas.”. SHA-256 do PDF: 1b50ab00af6310ca41a9fb3a8a80f8c7db67756ec3f321ba39d3a2704ac718cc.","order_index":1,"page":4,"excerpt":"Produtos químicos emitem gases corrosivos e nunca devem ser armazenados perto de motores e bombas."},{"question":"Como o excesso de calor afeta a vida útil do motor?","options":["Melhora o isolamento e evita falhas","Dispensa a ventilação do ambiente","Deteriora o isolamento e reduz a vida útil dos enrolamentos","Elimina a necessidade de manutenção","Aumenta indefinidamente a potência nominal"],"correct_answer":2,"explanation":"O texto associa temperatura excessiva à deterioração do isolamento e à redução da vida útil. Fonte: capítulo 7, página PDF 8. Trecho: “Ao longo do tempo o calor deteriora o isolamento do motor e o leva a falhas.”. SHA-256 do PDF: 1b50ab00af6310ca41a9fb3a8a80f8c7db67756ec3f321ba39d3a2704ac718cc.","order_index":2,"page":8,"excerpt":"Ao longo do tempo o calor deteriora o isolamento do motor e o leva a falhas."},{"question":"Na substituição do motor, por que não se recomenda instalar um motor maior indiscriminadamente?","options":["Porque reduz obrigatoriamente a sucção a zero","Porque elimina a vazão do filtro","Porque torna desnecessárias as grelhas","Porque aumenta o risco de aprisionamento por sucção","Porque altera apenas a aparência da casa de máquinas"],"correct_answer":3,"explanation":"A substituição deve respeitar o dimensionamento original e a potência adequada. Fonte: capítulo 7, página PDF 10. Trecho: “Motores maiores não devem ser usados porque aumentam o risco de aprisionamento de sucção.”. SHA-256 do PDF: 1b50ab00af6310ca41a9fb3a8a80f8c7db67756ec3f321ba39d3a2704ac718cc.","order_index":3,"page":10,"excerpt":"Motores maiores não devem ser usados porque aumentam o risco de aprisionamento de sucção."},{"question":"Qual fenômeno é definido como vaporização da água devido à redução da pressão durante o movimento?","options":["Condensação","Filtração","Oxidação","Decantação","Cavitação"],"correct_answer":4,"explanation":"Cavitação envolve formação de vapor por queda de pressão, podendo produzir ruídos e danos. Fonte: capítulo 7, página PDF 11. Trecho: “A cavitação (fenômeno de vaporização da água devido a redução da pressão”. SHA-256 do PDF: 1b50ab00af6310ca41a9fb3a8a80f8c7db67756ec3f321ba39d3a2704ac718cc.","order_index":4,"page":11,"excerpt":"A cavitação (fenômeno de vaporização da água devido a redução da pressão"},{"question":"Bolhas persistentes nos retornos e pré-filtro borbulhando sugerem qual investigação inicial?","options":["Entrada de ar na sucção, vedação da tampa e nível de água no skimmer","Troca imediata do termostato do aquecedor sem inspeção hidráulica","Aumento do ácido cianúrico para retirar as bolhas","Fechamento de todos os registros com a bomba ligada","Substituição do reagente DPD por vermelho de fenol"],"correct_answer":0,"explanation":"Nível baixo e vazamentos na sucção podem permitir entrada de ar e bolhas no retorno. Fonte: capítulo 7, página PDF 12. Trecho: “O nível da água da piscina pode ser muito baixo, permitindo que o ar se misture com a água através do skimmer.”. SHA-256 do PDF: 1b50ab00af6310ca41a9fb3a8a80f8c7db67756ec3f321ba39d3a2704ac718cc.","order_index":5,"page":12,"excerpt":"O nível da água da piscina pode ser muito baixo, permitindo que o ar se misture com a água através do skimmer."},{"question":"Antes de verificar possível obstrução do impulsor da bomba, qual é o primeiro cuidado indicado?","options":["Aumentar a rotação do motor","Desligar a bomba","Adicionar cloro ao cesto","Retirar o cesto com a bomba ligada","Fechar todos os retornos mantendo o motor ligado"],"correct_answer":1,"explanation":"A inspeção do impulsor começa com a bomba desligada e deve respeitar a qualificação e o manual. Fonte: capítulo 7, página PDF 13. Trecho: “desligando a bomba. Retire o cesto e verifi- que o impulsor;”. SHA-256 do PDF: 1b50ab00af6310ca41a9fb3a8a80f8c7db67756ec3f321ba39d3a2704ac718cc.","order_index":6,"page":13,"excerpt":"desligando a bomba. Retire o cesto e verifi- que o impulsor;"},{"question":"Qual característica é atribuída à bomba autoescorvante?","options":["Operar sem qualquer água por tempo ilimitado","Aquecer a piscina sem energia","Criar vácuo para puxar água mesmo sem a tubulação estar cheia","Dispensar toda vedação na sucção","Filtrar sem necessidade de meio filtrante"],"correct_answer":2,"explanation":"Autoescorvamento é a capacidade descrita de puxar água por criação de vácuo; não autoriza operação a seco. Fonte: capítulo 7, página PDF 14. Trecho: “Característica de bomba que puxa a água sem que a tubulação esteja cheia. Ela cria um vácuo que puxa a água.”. SHA-256 do PDF: 1b50ab00af6310ca41a9fb3a8a80f8c7db67756ec3f321ba39d3a2704ac718cc.","order_index":7,"page":14,"excerpt":"Característica de bomba que puxa a água sem que a tubulação esteja cheia. Ela cria um vácuo que puxa a água."},{"question":"No teste do balde, o que sugere a água da piscina cair abaixo do nível da água do balde?","options":["Ausência garantida de vazamento","Aumento obrigatório do cloro combinado","Necessidade de adicionar estabilizante","Possível vazamento na piscina ou no sistema","Funcionamento perfeito comprovado do filtro"],"correct_answer":3,"explanation":"O teste compara a perda da piscina com a perda por evaporação da água no balde. Fonte: capítulo 7, página PDF 17. Trecho: “Se o nível da piscina esti- ver abaixo do nível do balde, haverá um possível vazamento.”. SHA-256 do PDF: 1b50ab00af6310ca41a9fb3a8a80f8c7db67756ec3f321ba39d3a2704ac718cc.","order_index":8,"page":17,"excerpt":"Se o nível da piscina esti- ver abaixo do nível do balde, haverá um possível vazamento."},{"question":"Que condição pode corroer as linhas ou o trocador de calor e provocar vazamento no aquecedor?","options":["Temperatura do ar baixa, isoladamente","Registro de ocorrências atualizado","Cesto do skimmer limpo","Identificação correta das tubulações","pH baixo"],"correct_answer":4,"explanation":"O texto identifica pH baixo como possível causa de corrosão no aquecedor. Fonte: capítulo 7, página PDF 25. Trecho: “o pH baixo pode ter corroído linhas de tubulação ou trocador de calor.”. SHA-256 do PDF: 1b50ab00af6310ca41a9fb3a8a80f8c7db67756ec3f321ba39d3a2704ac718cc.","order_index":9,"page":25,"excerpt":"o pH baixo pode ter corroído linhas de tubulação ou trocador de calor."}],"8":[{"question":"Qual é uma finalidade central do histórico de operação e manutenção?","options":["Apoiar decisões, manutenção preventiva e operação segura","Dispensar verificações futuras da água","Substituir os manuais dos equipamentos","Eliminar todos os custos operacionais","Autorizar o funcionamento com equipamentos avariados"],"correct_answer":0,"explanation":"O histórico ajuda a compreender o comportamento da instalação e planejar ações e insumos. Fonte: capítulo 8, página PDF 1. Trecho: “o que ajuda no gerenciamento das instalações e de insumos”. SHA-256 do PDF: 525b0a215f5134edc4c87001b17aee6afd51bdcff371c5b08b584e0d2ebd5b87.","order_index":0,"page":1,"excerpt":"o que ajuda no gerenciamento das instalações e de insumos"},{"question":"O que caracteriza a manutenção preditiva?","options":["Apenas consertar após uma quebra","Acompanhamento periódico baseado em dados de monitoramento e inspeções","Trocar equipamentos sem analisar seu estado","Adiar qualquer inspeção até o fim da temporada","Aplicar sempre o mesmo produto químico"],"correct_answer":1,"explanation":"A preditiva usa dados para antecipar problemas e evitar intervenções corretivas maiores. Fonte: capítulo 8, página PDF 2. Trecho: “baseando-se na análise de dados coletados por meio de monitoramentos ou inspeções em campo.”. SHA-256 do PDF: 525b0a215f5134edc4c87001b17aee6afd51bdcff371c5b08b584e0d2ebd5b87.","order_index":1,"page":2,"excerpt":"baseando-se na análise de dados coletados por meio de monitoramentos ou inspeções em campo."},{"question":"Qual par deve ter seus valores anotados diariamente na relação mínima do capítulo?","options":["Somente dureza cálcica e custo da bomba","Somente alcalinidade e número do modelo","pH e teor residual do desinfetante","Somente preço dos produtos e data da compra","Somente nome do fornecedor e garantia"],"correct_answer":2,"explanation":"A relação mínima informa periodicidade diária para pH e desinfetante residual. Fonte: capítulo 8, página PDF 4. Trecho: “pH e teor residual do desinfetante (diário);”. SHA-256 do PDF: 525b0a215f5134edc4c87001b17aee6afd51bdcff371c5b08b584e0d2ebd5b87.","order_index":2,"page":4,"excerpt":"pH e teor residual do desinfetante (diário);"},{"question":"Que documentos dos produtos e equipamentos devem ser mantidos pelo responsável?","options":["Somente anúncios comerciais dos produtos","Apenas fotografias decorativas da instalação","Somente uma lista de marcas sem instruções","Fichas de segurança, manuais e certificados de garantia","Apenas notas sem identificação do fabricante"],"correct_answer":3,"explanation":"Esses documentos dão suporte a uso, manutenção e segurança. Fonte: capítulo 8, página PDF 5. Trecho: “manter cópias das fichas de informação de segurança de produtos químicos, assim como de todos os manuais e certificados de garantia”. SHA-256 do PDF: 525b0a215f5134edc4c87001b17aee6afd51bdcff371c5b08b584e0d2ebd5b87.","order_index":3,"page":5,"excerpt":"manter cópias das fichas de informação de segurança de produtos químicos, assim como de todos os manuais e certificados de garantia"},{"question":"Qual conjunto de informações químicas deve ser registrado segundo o capítulo?","options":["Apenas o preço do produto mais caro","Somente a cor da embalagem utilizada","Apenas o odor da água","Somente a marca do balde de aplicação","Adições químicas, leituras e consumo diário dos produtos"],"correct_answer":4,"explanation":"O histórico deve permitir acompanhar produtos adicionados, leituras e consumo. Fonte: capítulo 8, página PDF 8. Trecho: “adições químicas, níveis de água na piscina, leituras químicas”. SHA-256 do PDF: 525b0a215f5134edc4c87001b17aee6afd51bdcff371c5b08b584e0d2ebd5b87.","order_index":4,"page":8,"excerpt":"adições químicas, níveis de água na piscina, leituras químicas"},{"question":"O que deve identificar a responsabilidade por cada registro ou relatório?","options":["O nome do responsável pelo relatório","Apenas o volume da piscina","Somente a marca do reagente","Apenas o nome do condomínio","Somente o número do filtro"],"correct_answer":0,"explanation":"Cada registro deve indicar quem é responsável pelas informações. Fonte: capítulo 8, página PDF 9. Trecho: “Cada registro ou relatório deve incluir o nome do responsável pelo relatório.”. SHA-256 do PDF: 525b0a215f5134edc4c87001b17aee6afd51bdcff371c5b08b584e0d2ebd5b87.","order_index":5,"page":9,"excerpt":"Cada registro ou relatório deve incluir o nome do responsável pelo relatório."},{"question":"Quais informações temporais devem ser registradas a cada verificação?","options":["Somente o mês","Data e hora","Somente a estação do ano","Apenas o horário previsto da próxima visita","Apenas a data de instalação da piscina"],"correct_answer":1,"explanation":"A data e a hora permitem reconstruir a sequência das verificações. Fonte: capítulo 8, página PDF 12. Trecho: “É importante registrar a data e a hora sempre que as verificações forem realizadas.”. SHA-256 do PDF: 525b0a215f5134edc4c87001b17aee6afd51bdcff371c5b08b584e0d2ebd5b87.","order_index":6,"page":12,"excerpt":"É importante registrar a data e a hora sempre que as verificações forem realizadas."},{"question":"Uma condição insegura não foi corrigida antes do horário de abertura. Qual deve ser a conduta?","options":["Abrir normalmente se a água estiver azul","Permitir uso apenas aos adultos","Impedir o acesso à área da piscina até a correção","Aumentar o cloro para compensar","Remover os avisos para evitar reclamações"],"correct_answer":2,"explanation":"O texto determina corrigir a condição insegura antes da abertura; sem correção, o acesso deve ser impedido. Fonte: capítulo 8, página PDF 13. Trecho: “as pessoas não devem ter acesso à área da piscina.”. SHA-256 do PDF: 525b0a215f5134edc4c87001b17aee6afd51bdcff371c5b08b584e0d2ebd5b87.","order_index":7,"page":13,"excerpt":"as pessoas não devem ter acesso à área da piscina."},{"question":"Qual conjunto reúne tipos de emergência citados no capítulo?","options":["Somente falhas de cobrança de mensalidade","Somente mudanças de decoração","Apenas trocas comerciais de fornecedores","Emergências na água, doenças súbitas, desastres naturais e acidentes químicos","Apenas falta de mobiliário de lazer"],"correct_answer":3,"explanation":"O plano precisa considerar emergências humanas, ambientais e da própria instalação. Fonte: capítulo 8, página PDF 20. Trecho: “emergências de água, doenças súbitas, desastres naturais e emergências de instala- ções, como acidentes com produtos químicos”. SHA-256 do PDF: 525b0a215f5134edc4c87001b17aee6afd51bdcff371c5b08b584e0d2ebd5b87.","order_index":8,"page":20,"excerpt":"emergências de água, doenças súbitas, desastres naturais e emergências de instala- ções, como acidentes com produtos químicos"},{"question":"Após uma emergência, que conjunto de providências é destacado?","options":["Apagar os registros e reabrir imediatamente","Guardar os equipamentos sem inspeção","Dispensar reunião de avaliação em qualquer situação","Retomar o uso sem avaliar as condições de segurança","Completar relatórios, verificar equipamentos e substituir os problemáticos"],"correct_answer":4,"explanation":"Essas tarefas podem precisar ser concluídas antes da reabertura da instalação. Fonte: capítulo 8, página PDF 22. Trecho: “Completar relatórios, verificar equipamentos e substituir os equipamentos problemáticos”. SHA-256 do PDF: 525b0a215f5134edc4c87001b17aee6afd51bdcff371c5b08b584e0d2ebd5b87.","order_index":9,"page":22,"excerpt":"Completar relatórios, verificar equipamentos e substituir os equipamentos problemáticos"}],"9":[{"question":"Qual é o objetivo principal da manutenção preventiva?","options":["Evitar falhas por ações planejadas e regulares","Consertar equipamentos somente após a quebra","Aguardar ruídos intensos sem registrar alterações","Substituir todas as peças sem inspeção nem programação","Reabrir a piscina sem verificar a água"],"correct_answer":0,"explanation":"A preventiva é uma intervenção prevista e programada antes de uma possível falha. Fonte: capítulo 9, página PDF 1. Trecho: “programada antes do possível do surgimento de uma falha.”. SHA-256 do PDF: 6f8cdd20f09bc57dc302cf347c47e3c63912ca6ca34a9baf5f1d4cb604570a96.","order_index":0,"page":1,"excerpt":"programada antes do possível do surgimento de uma falha."},{"question":"O que caracteriza a manutenção corretiva?","options":["Inspeção programada antes de qualquer defeito","Intervenção para reparar um dano ou falha já ocorrido","Monitoramento de tendência de desgaste antes da quebra","Apenas preenchimento de um calendário sem execução","Lubrificação preventiva de uma peça em bom estado"],"correct_answer":1,"explanation":"A corretiva atua quando desgaste ou falha já está presente. Fonte: capítulo 9, página PDF 1. Trecho: “A manutenção corretiva ocorre quando já há desgastes ou falhas nos equipamentos”. SHA-256 do PDF: 6f8cdd20f09bc57dc302cf347c47e3c63912ca6ca34a9baf5f1d4cb604570a96.","order_index":1,"page":1,"excerpt":"A manutenção corretiva ocorre quando já há desgastes ou falhas nos equipamentos"},{"question":"Qual exemplo representa manutenção preditiva?","options":["Trocar uma bomba somente depois que queima","Limpar o deck sem observar equipamentos","Monitorar ruídos, pressão e temperatura para antecipar falhas","Esperar a tubulação estourar para comprar peças","Substituir todos os componentes ao acaso"],"correct_answer":2,"explanation":"Monitoramento da condição e inspeções para antecipar problemas caracterizam a preditiva. Fonte: capítulo 9, página PDF 1. Trecho: “baseando-se na análise de dados coletados por meio de monitoramentos ou inspeções em campo.”. SHA-256 do PDF: 6f8cdd20f09bc57dc302cf347c47e3c63912ca6ca34a9baf5f1d4cb604570a96.","order_index":2,"page":1,"excerpt":"baseando-se na análise de dados coletados por meio de monitoramentos ou inspeções em campo."},{"question":"Qual é o primeiro passo para saber quais equipamentos e itens integrarão o plano de manutenção?","options":["Substituir todos os equipamentos imediatamente","Definir datas sem consultar os equipamentos","Comprar produtos sem avaliar o estoque","Executar um inventário de todos os itens","Descartar os manuais existentes"],"correct_answer":3,"explanation":"O plano começa por identificar e inventariar seus itens. Fonte: capítulo 9, página PDF 5. Trecho: “Para isso, um inventário de todos os itens deve ser executado.”. SHA-256 do PDF: 6f8cdd20f09bc57dc302cf347c47e3c63912ca6ca34a9baf5f1d4cb604570a96.","order_index":3,"page":5,"excerpt":"Para isso, um inventário de todos os itens deve ser executado."},{"question":"Nome do equipamento, fabricante, modelo, manutenção e periodicidade devem constar de qual documento apresentado?","options":["Somente do aviso de profundidade","Exclusivamente do recibo de pagamento","Somente da lista de banhistas","Exclusivamente do relatório meteorológico","Formulário de inventário"],"correct_answer":4,"explanation":"A seção Formulário de Inventário lista esses campos; não os atribui a um manual elaborado pelo operador. Fonte: capítulo 9, página PDF 7. Trecho: “À medida que o inventário é realizado, as seguintes informações devem ser registradas para cada item:”. SHA-256 do PDF: 6f8cdd20f09bc57dc302cf347c47e3c63912ca6ca34a9baf5f1d4cb604570a96.","order_index":4,"page":7,"excerpt":"À medida que o inventário é realizado, as seguintes informações devem ser registradas para cada item:"},{"question":"Todos os equipamentos exigem inspeção diária?","options":["Não; a periodicidade varia e deve seguir manuais e necessidades","Sim; todos têm exatamente a mesma rotina","Não; nenhum equipamento precisa de inspeção diária","Sim; inspeções semanais são sempre proibidas","Não; a periodicidade depende somente da cor do equipamento"],"correct_answer":0,"explanation":"O capítulo prevê frequências diárias, semanais, mensais, trimestrais, sazonais ou anuais conforme o item. Fonte: capítulo 9, página PDF 13. Trecho: “Nem todos os equipamentos operacionais exigem inspeção diária.”. SHA-256 do PDF: 6f8cdd20f09bc57dc302cf347c47e3c63912ca6ca34a9baf5f1d4cb604570a96.","order_index":5,"page":13,"excerpt":"Nem todos os equipamentos operacionais exigem inspeção diária."},{"question":"Qual atividade é descrita como responsabilidade contínua da equipe, entre o desbloqueio e o bloqueio da instalação?","options":["Manutenção exclusivamente corretiva","Manutenção de rotina","Substituição emergencial de motor","Inspeção única de inauguração","Reforma estrutural sem programação"],"correct_answer":1,"explanation":"A rotina engloba as tarefas contínuas de abertura, operação e fechamento. Fonte: capítulo 9, página PDF 17. Trecho: “A manutenção diária ou de rotina é o trabalho realizado pela equipe como uma responsabilidade contínua.”. SHA-256 do PDF: 6f8cdd20f09bc57dc302cf347c47e3c63912ca6ca34a9baf5f1d4cb604570a96.","order_index":6,"page":17,"excerpt":"A manutenção diária ou de rotina é o trabalho realizado pela equipe como uma responsabilidade contínua."},{"question":"Qual é a finalidade da escovação regular das paredes da piscina ou spa?","options":["Substituir permanentemente o desinfetante","Eliminar a necessidade de qualquer filtração","Desprender detritos e facilitar sua remoção pela circulação","Corrigir automaticamente a dureza cálcica","Aumentar a concentração de sólidos dissolvidos"],"correct_answer":2,"explanation":"A escovação solta os resíduos das superfícies para facilitar sua remoção. Fonte: capítulo 9, página PDF 21. Trecho: “A escovação remove os detritos das paredes da piscina ou spa e permite uma remoção melhorada através do fluxo de circulação.”. SHA-256 do PDF: 6f8cdd20f09bc57dc302cf347c47e3c63912ca6ca34a9baf5f1d4cb604570a96.","order_index":7,"page":21,"excerpt":"A escovação remove os detritos das paredes da piscina ou spa e permite uma remoção melhorada através do fluxo de circulação."},{"question":"Qual situação caracteriza a manutenção sazonal?","options":["Descarte diário de toda a água em qualquer estação","Troca obrigatória de bomba após cada banho","Aquecimento máximo da água durante toda a noite","Fechamento da piscina ou spa por vários meses, por exemplo durante o inverno","Apenas fechamento do portão sem cuidar da água"],"correct_answer":3,"explanation":"A manutenção sazonal prepara e protege a instalação durante períodos prolongados sem uso. Fonte: capítulo 9, página PDF 26. Trecho: “situações de fechamento da piscina ou spa por vários meses, devido ao inverno”. SHA-256 do PDF: 6f8cdd20f09bc57dc302cf347c47e3c63912ca6ca34a9baf5f1d4cb604570a96.","order_index":8,"page":26,"excerpt":"situações de fechamento da piscina ou spa por vários meses, devido ao inverno"},{"question":"Por que uma piscina vazia em região com lençol freático alto exige cuidado com pressão hidrostática?","options":["Porque a pressão elimina o risco de danos estruturais","Porque a água subterrânea sempre impede qualquer movimento","Porque a piscina vazia fica obrigatoriamente mais pesada","Porque o lençol freático altera somente a cor do revestimento","Porque a pressão ascendente pode fazer o casco flutuar para fora do solo"],"correct_answer":4,"explanation":"O capítulo explica o risco de pressão ascendente e o papel das válvulas de alívio. Fonte: capítulo 9, página PDF 28. Trecho: “Uma piscina vazia pode flutuar para fora do solo se o lençol freático subir muito.”. SHA-256 do PDF: 6f8cdd20f09bc57dc302cf347c47e3c63912ca6ca34a9baf5f1d4cb604570a96.","order_index":9,"page":28,"excerpt":"Uma piscina vazia pode flutuar para fora do solo se o lençol freático subir muito."}],"10":[{"question":"Qual objetivo da revisão da NBR 10339:2018 é descrito no capítulo?","options":["Harmonizar critérios técnicos de segurança, operação, recirculação e tratamento","Eliminar a necessidade de manutenção preventiva","Permitir operação sem tratamento de água","Substituir o projeto técnico por observação visual","Restringir a norma apenas à cor da piscina"],"correct_answer":0,"explanation":"A introdução relaciona a revisão à segurança e ao desempenho da instalação. Fonte: capítulo 10, página PDF 1. Trecho: “harmonizar os critérios técni- cos para melhoria da segurança para os usuários de piscinas”. SHA-256 do PDF: c418a3cb0012d598cc8eca6be37cbfc9dd6bb18ded72aaafacb3a8d6f2666c4f.","order_index":0,"page":1,"excerpt":"harmonizar os critérios técni- cos para melhoria da segurança para os usuários de piscinas"},{"question":"Como o capítulo classifica, quanto ao uso, as piscinas de condomínios?","options":["Residenciais privativas","Residenciais coletivas","Públicas de acesso irrestrito","Exclusivamente desportivas","Naturais por definição"],"correct_answer":1,"explanation":"Condomínios aparecem explicitamente na categoria residencial coletiva. Fonte: capítulo 10, página PDF 2. Trecho: “residenciais coletivas (condomí- nios)”. SHA-256 do PDF: c418a3cb0012d598cc8eca6be37cbfc9dd6bb18ded72aaafacb3a8d6f2666c4f.","order_index":1,"page":2,"excerpt":"residenciais coletivas (condomí- nios)"},{"question":"As categorias “água com condicionamento” e “água sem condicionamento” referem-se a qual critério?","options":["Suprimento e tratamento de água","Finalidade","Condicionamento da temperatura","Concepção natural ou artificial","Local aberto ou coberto"],"correct_answer":2,"explanation":"O PDF associa essas categorias ao condicionamento da temperatura, corrigindo a atribuição equivocada da planilha. Fonte: capítulo 10, página PDF 2. Trecho: “Quanto ao CONDICIONAMENTO DA TEMPERATURA”. SHA-256 do PDF: c418a3cb0012d598cc8eca6be37cbfc9dd6bb18ded72aaafacb3a8d6f2666c4f.","order_index":2,"page":2,"excerpt":"Quanto ao CONDICIONAMENTO DA TEMPERATURA"},{"question":"Qual alternativa apresenta somente classificações de piscina quanto à finalidade?","options":["Públicas, de hospedaria e residenciais coletivas","Abertas, cobertas-abertas e cobertas-fechadas","Naturais e artificiais","Desportivas, recreativas, mistas, infantis e especiais","Água doce, medicinal e salgada"],"correct_answer":3,"explanation":"O conjunto correto é o grupo definido por finalidade. Fonte: capítulo 10, página PDF 2. Trecho: “Quanto à FINALIDADE, as piscinas podem ser desportivas, recreativas, mistas, infantis e especiais”. SHA-256 do PDF: c418a3cb0012d598cc8eca6be37cbfc9dd6bb18ded72aaafacb3a8d6f2666c4f.","order_index":3,"page":2,"excerpt":"Quanto à FINALIDADE, as piscinas podem ser desportivas, recreativas, mistas, infantis e especiais"},{"question":"Segundo o capítulo, qual é a recomendação de quantidade de skimmers em piscinas residenciais privadas e coletivas?","options":["Um a cada 5 m²","Um a cada 10 m²","Um a cada 100 m²","Um a cada 500 m²","Um a cada 50 m² de superfície de água"],"correct_answer":4,"explanation":"O valor é específico para skimmers e para as tipologias citadas no capítulo. Fonte: capítulo 10, página PDF 13. Trecho: “instalação a cada 50 m² em piscinas residenciais privadas e residenciais coletivas”. SHA-256 do PDF: c418a3cb0012d598cc8eca6be37cbfc9dd6bb18ded72aaafacb3a8d6f2666c4f.","order_index":4,"page":13,"excerpt":"instalação a cada 50 m² em piscinas residenciais privadas e residenciais coletivas"},{"question":"No arranjo com dois ralos de fundo, quais características são indicadas no PDF?","options":["Ralos interligados, hidraulicamente equilibrados e separados por no mínimo 1,5 m","Ralos independentes, sem grelha, separados por 15 cm","Ralos vedados e sem conexão à circulação","Ralos sem equilíbrio hidráulico, separados por 50 cm","Um ralo aberto e um bocal de aspiração sem tampa"],"correct_answer":0,"explanation":"A pergunta trata do arranjo de dois ralos; o texto também admite outros arranjos, portanto não o apresenta como única solução possível. Fonte: capítulo 10, página PDF 10. Trecho: “2 ralos de fundo interligados distantes no mínimo 1,5 metros e hidraulicamente equilibrados.”. SHA-256 do PDF: c418a3cb0012d598cc8eca6be37cbfc9dd6bb18ded72aaafacb3a8d6f2666c4f.","order_index":5,"page":10,"excerpt":"2 ralos de fundo interligados distantes no mínimo 1,5 metros e hidraulicamente equilibrados."},{"question":"Qual limite de velocidade através da grade do ralo é citado na apostila?","options":["1,0 m/s","0,5 m/s","1,5 m/s","2,0 m/s","5,0 m/s"],"correct_answer":1,"explanation":"O limite mencionado no capítulo para escoamento pelas aberturas da grelha é 0,5 m/s. Fonte: capítulo 10, página PDF 8. Trecho: “velocidade máxima de escoa- mento seja 0,5 m/s por meio das aberturas da grelha.”. SHA-256 do PDF: c418a3cb0012d598cc8eca6be37cbfc9dd6bb18ded72aaafacb3a8d6f2666c4f.","order_index":6,"page":8,"excerpt":"velocidade máxima de escoa- mento seja 0,5 m/s por meio das aberturas da grelha."},{"question":"Qual é a função principal da grelha antiaprisionamento indicada para o ralo de fundo?","options":["Aumentar a sucção sobre o corpo do banhista","Substituir todos os equipamentos de salvamento","Prevenir entrelaçamento de cabelos e aprisionamento por sucção","Reter apenas a água aquecida no tanque","Eliminar a necessidade de dimensionamento hidráulico"],"correct_answer":2,"explanation":"A grelha é um dispositivo de redução do risco de aprisionamento. Fonte: capítulo 10, página PDF 8. Trecho: “prevenir entrelaçamento dos cabe- los ou aprisionamento por sucção de partes do corpo.”. SHA-256 do PDF: c418a3cb0012d598cc8eca6be37cbfc9dd6bb18ded72aaafacb3a8d6f2666c4f.","order_index":7,"page":8,"excerpt":"prevenir entrelaçamento dos cabe- los ou aprisionamento por sucção de partes do corpo."},{"question":"Qual combinação descreve a localização do botão de emergência no capítulo?","options":["Dentro da casa de máquinas trancada e sem sinalização","Submerso junto ao ralo mais profundo","Em local oculto, acessível apenas ao fabricante","Fácil acesso e visualização, próximo ao tanque e no mínimo a 2 m da borda","A menos de 10 cm da borda e sob a capa"],"correct_answer":3,"explanation":"O texto exige fácil acesso e visualização e estabelece distância mínima de dois metros da borda. Fonte: capítulo 10, página PDF 6. Trecho: “próximo ao tanque e no mínimo a 2 m da borda da piscina”. SHA-256 do PDF: c418a3cb0012d598cc8eca6be37cbfc9dd6bb18ded72aaafacb3a8d6f2666c4f.","order_index":8,"page":6,"excerpt":"próximo ao tanque e no mínimo a 2 m da borda da piscina"},{"question":"Na tabela do capítulo, qual é o tempo máximo de filtração de uma piscina residencial coletiva com profundidade média de 1,50 m, fora da condição de alta ocupação indicada na última coluna?","options":["2 horas","4 horas","8 horas","12 horas","6 horas"],"correct_answer":4,"explanation":"A coluna de pública/coletiva/hospedaria/residencial coletiva indica 6 horas; é tempo máximo, não mínimo, e a alta ocupação tem coluna própria. Fonte: capítulo 10, página PDF 16. Trecho: “| 0,60 a 1,50 | 8 | 6 | 4 |”. SHA-256 do PDF: c418a3cb0012d598cc8eca6be37cbfc9dd6bb18ded72aaafacb3a8d6f2666c4f.","order_index":9,"page":16,"excerpt":"| 0,60 a 1,50 | 8 | 6 | 4 |"}],"11":[{"question":"Quais são os dois meios de movimentação/captação da água apresentados?","options":["Sucção direta e transbordamento","Somente aquecimento e evaporação","Somente aspiração e decantação","Cloração e correção de pH","Convecção e radiação térmica"],"correct_answer":0,"explanation":"A seção Sistemas de captação da água apresenta sucção direta e transbordamento. Fonte: capítulo 11, página PDF 3. Trecho: “Sucção direta ou”. SHA-256 do PDF: 7004de349cec1e3d6461ca0f9f63966d37f86ed737fb2644db681a0b7946791b.","order_index":0,"page":3,"excerpt":"Sucção direta ou"},{"question":"No sistema de transbordamento descrito, para qual reservatório segue a água coletada pelas calhas ou skimmers?","options":["Interior do motor elétrico","Tanque de compensação","Embalagem do reagente","Circuito de gás do aquecedor","Cesto de produtos químicos concentrados"],"correct_answer":1,"explanation":"No transbordamento, a água coletada segue ao tanque de compensação. Fonte: capítulo 11, página PDF 4. Trecho: “direcionada para um tanque, também conhecido como tanque de compensa- ção.”. SHA-256 do PDF: 7004de349cec1e3d6461ca0f9f63966d37f86ed737fb2644db681a0b7946791b.","order_index":1,"page":4,"excerpt":"direcionada para um tanque, também conhecido como tanque de compensa- ção."},{"question":"Qual função o posicionamento das entradas de retorno deve cumprir?","options":["Concentrar produtos em um único ponto parado","Impedir a homogeneização da temperatura","Distribuir e diluir produtos e evitar zonas estagnadas","Desviar a água para fora da piscina","Eliminar a captação de água pelo sistema"],"correct_answer":2,"explanation":"As entradas de retorno favorecem mistura dos produtos e temperatura homogênea, evitando pontos estagnados. Fonte: capítulo 11, página PDF 25. Trecho: “fornecendo a distribuição e diluição necessária dos produtos químicos”. SHA-256 do PDF: 7004de349cec1e3d6461ca0f9f63966d37f86ed737fb2644db681a0b7946791b.","order_index":2,"page":25,"excerpt":"fornecendo a distribuição e diluição necessária dos produtos químicos"},{"question":"Como se calcula a taxa de recirculação T apresentada no capítulo?","options":["T = volume do tanque ÷ área da superfície","T = vazão × profundidade média","T = pH × volume recirculado","T = volume recirculado em 24 h ÷ volume do tanque","T = volume do tanque + tempo de filtração"],"correct_answer":3,"explanation":"Vr é o volume recirculado em 24 horas e Vp é o volume contido no tanque. Fonte: capítulo 11, página PDF 8. Trecho: “Fórmula - T=Vr/Vp”. SHA-256 do PDF: 7004de349cec1e3d6461ca0f9f63966d37f86ed737fb2644db681a0b7946791b.","order_index":3,"page":8,"excerpt":"Fórmula - T=Vr/Vp"},{"question":"O que é um ponto cego de circulação?","options":["O local de maior movimentação da água","O interior de um frasco de teste vazio","Uma região onde o cloro é produzido automaticamente","Um bocal com vazão uniforme e desobstruída","Uma área de fluxo deficiente onde água e químicos não circulam adequadamente"],"correct_answer":4,"explanation":"Um ponto cego tem circulação deficiente e pode acumular impurezas ou favorecer algas. Fonte: capítulo 11, página PDF 13. Trecho: “áreas em que o sistema de circulação não faz a água circular”. SHA-256 do PDF: 7004de349cec1e3d6461ca0f9f63966d37f86ed737fb2644db681a0b7946791b.","order_index":4,"page":13,"excerpt":"áreas em que o sistema de circulação não faz a água circular"},{"question":"Qual procedimento pode ajudar a identificar pontos cegos?","options":["Observar o percurso de um corante apropriado com a bomba ligada","Avaliar somente o odor da água com a bomba desligada","Contar os degraus sem observar o fluxo","Medir apenas a tensão elétrica do aquecedor","Conferir a validade do reagente sem analisar a água"],"correct_answer":0,"explanation":"O teste de corante verifica a distribuição da água durante a circulação. Sua execução requer as precauções e orientações específicas do capítulo. Fonte: capítulo 11, página PDF 27. Trecho: “o sistema de circulação deve estar em funcionamento nor- mal”. SHA-256 do PDF: 7004de349cec1e3d6461ca0f9f63966d37f86ed737fb2644db681a0b7946791b.","order_index":5,"page":27,"excerpt":"o sistema de circulação deve estar em funcionamento nor- mal"},{"question":"Qual recurso de muitas entradas de retorno permite ajustar a direção do fluxo?","options":["Somente o manômetro da bomba","Bicos de saída de água direcionáveis","O cesto removível do skimmer","A etiqueta de validade do reagente","O termostato do aquecedor"],"correct_answer":1,"explanation":"O texto descreve bocais direcionáveis nas paredes para ajustar o fluxo. Fonte: capítulo 11, página PDF 25. Trecho: “bicos de saída de água direcionáveis para ajustes”. SHA-256 do PDF: 7004de349cec1e3d6461ca0f9f63966d37f86ed737fb2644db681a0b7946791b.","order_index":6,"page":25,"excerpt":"bicos de saída de água direcionáveis para ajustes"},{"question":"Qual é a função do manômetro instalado na saída da bomba?","options":["Medir cloro livre por reação colorimétrica","Determinar diretamente a dureza cálcica","Medir a pressão do fluido para acompanhar o desempenho da bomba","Calcular o número de banhistas automaticamente","Medir a umidade do ar na casa de máquinas"],"correct_answer":2,"explanation":"A instalação na saída permite acompanhar o desempenho hidráulico da bomba. Fonte: capítulo 11, página PDF 22. Trecho: “Equipamento para medir pressões de fluidos.”. SHA-256 do PDF: 7004de349cec1e3d6461ca0f9f63966d37f86ed737fb2644db681a0b7946791b.","order_index":7,"page":22,"excerpt":"Equipamento para medir pressões de fluidos."},{"question":"Qual fórmula permite calcular a vazão de projeto em m³/h?","options":["Volume da piscina em m³ × tempo de recirculação em horas","Tempo em horas ÷ volume em m³","Volume em litros + tempo em horas","Volume da piscina em m³ ÷ tempo de recirculação em horas","Área em m² ÷ concentração de cloro"],"correct_answer":3,"explanation":"Volume dividido pelo tempo fornece a vazão de projeto em m³/h. Fonte: capítulo 11, página PDF 7. Trecho: “divida o volume total de água da piscina (m³) pelo tempo máximo de recirculação (h)”. SHA-256 do PDF: 7004de349cec1e3d6461ca0f9f63966d37f86ed737fb2644db681a0b7946791b.","order_index":8,"page":7,"excerpt":"divida o volume total de água da piscina (m³) pelo tempo máximo de recirculação (h)"},{"question":"Uma piscina de 100.000 litros tem vazão efetiva constante de 1.000 L/min durante 24 horas. Qual é sua taxa de recirculação nesse período?","options":["1,44","2,4","10","24","14,4"],"correct_answer":4,"explanation":"Vr = 1.000 × 60 × 24 = 1.440.000 L; T = 1.440.000 ÷ 100.000 = 14,4. Fonte: capítulo 11, página PDF 8. Trecho: “É a relação (T) entre o volume de água recirculada pelo sistema em 24 h (Vr), e o volume de água contido no tanque (Vp).”. SHA-256 do PDF: 7004de349cec1e3d6461ca0f9f63966d37f86ed737fb2644db681a0b7946791b.","order_index":9,"page":8,"excerpt":"É a relação (T) entre o volume de água recirculada pelo sistema em 24 h (Vr), e o volume de água contido no tanque (Vp)."}],"12":[{"question":"Qual faixa de temperatura é indicada para piscinas de recreação no PDF?","options":["27 °C a 29 °C","18 °C a 20 °C","21 °C a 23 °C","30 °C a 32 °C","36 °C a 38 °C"],"correct_answer":0,"explanation":"O PDF indica de 27 a 29 °C para piscinas de recreação. Fonte: capítulo 12, página PDF 1. Trecho: “Piscinas de recreação – 27 °C a 29 °C;”. SHA-256 do PDF: fa3f1eb3e097be3a4f16856b94df218e3b77ce40601cb5e8cdb7e790a55e6a93.","order_index":0,"page":1,"excerpt":"Piscinas de recreação – 27 °C a 29 °C;"},{"question":"Qual faixa de temperatura é indicada para spas no PDF?","options":["20 °C a 22 °C","36 °C a 38 °C","25 °C a 28 °C","27 °C a 29 °C","30 °C a 32 °C"],"correct_answer":1,"explanation":"O intervalo indicado para spas é 36 a 38 °C. Fonte: capítulo 12, página PDF 1. Trecho: “Spas - 36 °C a 38 °C;”. SHA-256 do PDF: fa3f1eb3e097be3a4f16856b94df218e3b77ce40601cb5e8cdb7e790a55e6a93.","order_index":1,"page":1,"excerpt":"Spas - 36 °C a 38 °C;"},{"question":"Qual alternativa contém os quatro mecanismos de perda de calor listados no capítulo?","options":["Filtração, aspiração, cloração e decantação","Oxidação, neutralização, titulação e diluição","Evaporação, convecção, condução e radiação térmica","Sucção, retorno, bombeamento e medição","Transbordamento, dosagem, calibração e inspeção"],"correct_answer":2,"explanation":"A lista apresentada é evaporação, convecção, condução e radiação térmica. Fonte: capítulo 12, página PDF 2. Trecho: “As perdas de energia (temperatura) podem ser por 4 mecanismos:”. SHA-256 do PDF: fa3f1eb3e097be3a4f16856b94df218e3b77ce40601cb5e8cdb7e790a55e6a93.","order_index":2,"page":2,"excerpt":"As perdas de energia (temperatura) podem ser por 4 mecanismos:"},{"question":"Qual benefício operacional a capa térmica proporciona?","options":["Substituir uma capa de proteção contra quedas","Eliminar a necessidade de cloro e testes","Aumentar propositalmente a evaporação noturna","Reduzir perda de calor e evaporação da água","Substituir a bomba de circulação"],"correct_answer":3,"explanation":"A capa térmica reduz perdas térmicas, incluindo as associadas à evaporação; não é capa de proteção. Fonte: capítulo 12, página PDF 6. Trecho: “uma simples ação como a instalação de uma capa térmica pode di- minuir consideravelmente estas perdas.”. SHA-256 do PDF: fa3f1eb3e097be3a4f16856b94df218e3b77ce40601cb5e8cdb7e790a55e6a93.","order_index":3,"page":6,"excerpt":"uma simples ação como a instalação de uma capa térmica pode di- minuir consideravelmente estas perdas."},{"question":"Qual limitação do aquecimento solar é destacada?","options":["Impossibilidade de circular água nos coletores","Necessidade obrigatória de queimar GLP nas placas","Geração de calor por resistência elétrica em todas as placas","Funcionamento exclusivo em ambientes sem luz","Dependência da radiação solar e das condições climáticas"],"correct_answer":4,"explanation":"O aquecimento solar depende de radiação suficiente e pode precisar de apoio. Fonte: capítulo 12, página PDF 14. Trecho: “quando não há sol suficiente, entra em ação o sistema de apoio”. SHA-256 do PDF: fa3f1eb3e097be3a4f16856b94df218e3b77ce40601cb5e8cdb7e790a55e6a93.","order_index":4,"page":14,"excerpt":"quando não há sol suficiente, entra em ação o sistema de apoio"},{"question":"De onde a bomba de calor retira energia térmica para aquecer a piscina?","options":["Do ar ambiente, transferindo-a para a água por um circuito refrigerante","Exclusivamente da combustão de GLP","Da dissolução de bicarbonato de sódio","Somente de uma resistência imersa sem compressor","Da reação entre cloro e ácido no mesmo balde"],"correct_answer":0,"explanation":"A bomba de calor troca energia com o ar e a transfere para a água por ciclo frigorífico. Fonte: capítulo 12, página PDF 11. Trecho: “troca de calor com o ar através de um ciclo frigorífi- co”. SHA-256 do PDF: fa3f1eb3e097be3a4f16856b94df218e3b77ce40601cb5e8cdb7e790a55e6a93.","order_index":5,"page":11,"excerpt":"troca de calor com o ar através de um ciclo frigorífi- co"},{"question":"O que significa uma bomba de calor com COP igual a 5?","options":["Consumir 5 kW elétricos para entregar 1 kW térmico","Entregar 5 kW térmicos para cada 1 kW elétrico consumido nas condições de referência","Aquecer sempre a água em exatamente 5 minutos","Manter a piscina obrigatoriamente a 5 °C","Recircular o volume da piscina cinco vezes por minuto"],"correct_answer":1,"explanation":"COP é a relação entre calor entregue e consumo elétrico; COP 5 significa razão 5:1 nas condições informadas. Fonte: capítulo 12, página PDF 18. Trecho: “como o COP é 5 dividiremos a potência entregue por 5 para encontrarmos o consumo”. SHA-256 do PDF: fa3f1eb3e097be3a4f16856b94df218e3b77ce40601cb5e8cdb7e790a55e6a93.","order_index":6,"page":18,"excerpt":"como o COP é 5 dividiremos a potência entregue por 5 para encontrarmos o consumo"},{"question":"Por que a instalação e a manutenção do aquecedor a gás devem seguir rigorosamente o manual?","options":["Porque o manual substitui a inspeção de qualquer defeito","Porque elimina a necessidade de ventilação adequada","Falhas podem causar vazamentos e graves riscos à vida","Porque permite reparos por pessoas sem qualificação","Porque dispensa a verificação de funcionamento"],"correct_answer":2,"explanation":"O capítulo alerta para vazamentos e risco de vida decorrentes de problemas de instalação ou manutenção. Fonte: capítulo 12, página PDF 10. Trecho: “Falta de manutenção ou problemas na instalação po- dem ocasionar vazamentos e graves riscos de vida.”. SHA-256 do PDF: fa3f1eb3e097be3a4f16856b94df218e3b77ce40601cb5e8cdb7e790a55e6a93.","order_index":7,"page":10,"excerpt":"Falta de manutenção ou problemas na instalação po- dem ocasionar vazamentos e graves riscos de vida."},{"question":"No modelo didático do capítulo, com c = 1 e sem perdas, qual fórmula fornece o calor em kcal a partir do volume V em m³ e da variação ΔT em °C?","options":["Q = volume ÷ variação de temperatura × 1.000","Q = volume × temperatura desejada sem considerar a inicial","Q = área da superfície × pressão do filtro","Q = volume × variação de temperatura × 1.000","Q = volume + variação de temperatura + 1.000"],"correct_answer":3,"explanation":"Usando a água como referência do exemplo, 1 m³ = 1.000 L; com c = 1, a energia em kcal é volume em m³ × variação em °C × 1.000. Fonte: capítulo 12, página PDF 16. Trecho: “Q = m x c x (tf – ti)”. SHA-256 do PDF: fa3f1eb3e097be3a4f16856b94df218e3b77ce40601cb5e8cdb7e790a55e6a93.","order_index":8,"page":16,"excerpt":"Q = m x c x (tf – ti)"},{"question":"Sem considerar perdas, quantas kcal são necessárias para aquecer 30 m³ de água de 20 °C a 28 °C?","options":["24.000 kcal","60.000 kcal","84.000 kcal","840.000 kcal","240.000 kcal"],"correct_answer":4,"explanation":"Aplicando o mesmo modelo: 30.000 L × 1 × (28 − 20) = 240.000 kcal, sem considerar perdas. Fonte: capítulo 12, página PDF 17. Trecho: “Q = 20.000 x 1 x (27-23) Q = 80.000 kcal”. SHA-256 do PDF: fa3f1eb3e097be3a4f16856b94df218e3b77ce40601cb5e8cdb7e790a55e6a93.","order_index":9,"page":17,"excerpt":"Q = 20.000 x 1 x (27-23) Q = 80.000 kcal"}]}$bank$::jsonb;
